// Open/Closed + Dependency Inversion: add a discount type without touching OrderService
interface DiscountPolicy { long discountCents(Order o); }

class NoDiscount implements DiscountPolicy { public long discountCents(Order o) { return 0; } }
class PercentDiscount implements DiscountPolicy {
    private final int percent;
    PercentDiscount(int percent) { this.percent = percent; }
    public long discountCents(Order o) { return o.totalCents() * percent / 100; }
}

interface OrderRepository { void save(Order o); }   // owned by the domain; infra implements it

class OrderService {
    private final OrderRepository repo;
    private final DiscountPolicy discount;
    OrderService(OrderRepository repo, DiscountPolicy discount) { this.repo = repo; this.discount = discount; }

    void place(Order o) {
        o.applyDiscount(discount.discountCents(o));
        repo.save(o);
    }
}
// Production: new OrderService(new PostgresOrderRepository(ds), new PercentDiscount(10))
// Test:       new OrderService(new InMemoryOrderRepository(), new NoDiscount())

# Liskov violation and the fix by composition: a read-only view is not a Rectangle subclass
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

class Rectangle(Shape):
    def __init__(self, w: float, h: float): self.w, self.h = w, h
    def area(self): return self.w * self.h

class Square(Shape):                      # separate type, no inheritance from Rectangle
    def __init__(self, side: float): self.side = side
    def area(self): return self.side ** 2

# Client depends only on the abstraction (Dependency Inversion) and works for every Shape (Liskov)
def total_area(shapes: list[Shape]) -> float:
    return sum(s.area() for s in shapes)

// Interface Segregation: a read-only consumer gets a read-only interface
interface ReadRepo<T> { get(id: string): Promise<T | null>; list(): Promise<T[]> }
interface WriteRepo<T> { save(item: T): Promise<void>; remove(id: string): Promise<void> }
type Repo<T> = ReadRepo<T> & WriteRepo<T>;

class ReportService {
  constructor(private readonly users: ReadRepo<User>) {}          // cannot write by accident; trivial to fake in tests
  async activeCount() { return (await this.users.list()).filter((u) => u.active).length; }
}

// Decorator: add retry and logging around any PaymentGateway without changing it
interface PaymentGateway { charge(amountCents: number, token: string): Promise<{ id: string; ok: boolean }> }

class RetryingGateway implements PaymentGateway {
  constructor(private inner: PaymentGateway, private attempts = 3) {}
  async charge(amountCents: number, token: string) {
    let lastErr: unknown;
    for (let i = 0; i < this.attempts; i++) {
      try { return await this.inner.charge(amountCents, token); }
      catch (e) { lastErr = e; await new Promise((r) => setTimeout(r, 2 ** i * 100)); }
    }
    throw lastErr;
  }
}

class LoggingGateway implements PaymentGateway {
  constructor(private inner: PaymentGateway, private log = console) {}
  async charge(amountCents: number, token: string) {
    const t = Date.now();
    const r = await this.inner.charge(amountCents, token);
    this.log.info(`charge ${amountCents} -> ${r.ok} in ${Date.now() - t}ms`);
    return r;
  }
}

// Compose layers: logging( retry( adapter ) )
const gateway: PaymentGateway = new LoggingGateway(new RetryingGateway(new StripeAdapter(stripe)));

// Composite: files and folders share one interface
interface Node { long size(); }
record FileNode(String name, long bytes) implements Node { public long size() { return bytes; } }
class Folder implements Node {
    private final List<Node> children = new ArrayList<>();
    Folder add(Node n) { children.add(n); return this; }
    public long size() { return children.stream().mapToLong(Node::size).sum(); }   // recursion hidden in the structure
}
// new Folder().add(new FileNode("a", 10)).add(new Folder().add(new FileNode("b", 5))).size() == 15

// Thread-safe lazy singleton via the holder idiom (still prefer injecting a single instance)
final class Config {
    private Config() {}
    private static class Holder { static final Config INSTANCE = new Config(); }
    static Config get() { return Holder.INSTANCE; }
}

