// Observer + State: an order with explicit transitions and subscribers
type Status = "pending" | "paid" | "shipped" | "cancelled";
const allowed: Record<Status, Status[]> = { pending: ["paid", "cancelled"], paid: ["shipped", "cancelled"], shipped: [], cancelled: [] };

type Listener = (order: Order, from: Status, to: Status) => void;

class Order {
  private status: Status = "pending";
  private listeners = new Set<Listener>();
  subscribe(l: Listener) { this.listeners.add(l); return () => this.listeners.delete(l); } // returns unsubscribe (avoid leaks)
  transition(to: Status) {
    if (!allowed[this.status].includes(to)) throw new Error(`illegal ${this.status} -> ${to}`);
    const from = this.status;
    this.status = to;
    for (const l of this.listeners) { try { l(this, from, to); } catch (e) { console.error(e); } } // one bad observer can't break others
  }
}

# Command with undo: a tiny text-editor history
class Command:
    def execute(self): ...
    def undo(self): ...

class Insert(Command):
    def __init__(self, doc, pos, text): self.doc, self.pos, self.text = doc, pos, text
    def execute(self): self.doc.text = self.doc.text[:self.pos] + self.text + self.doc.text[self.pos:]
    def undo(self):    self.doc.text = self.doc.text[:self.pos] + self.doc.text[self.pos + len(self.text):]

class Editor:
    def __init__(self, doc): self.doc, self.done, self.undone = doc, [], []
    def run(self, cmd): cmd.execute(); self.done.append(cmd); self.undone.clear()
    def undo(self):
        if self.done: c = self.done.pop(); c.undo(); self.undone.append(c)
    def redo(self):
        if self.undone: c = self.undone.pop(); c.execute(); self.done.append(c)
